
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_apbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_apbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.328093928899573e+00, -4.246747732443080e+00, -4.132886966689004e+00, -3.975422346707385e+00, -3.761401394244492e+00, -3.477686613628900e+00, -3.114816850850500e+00, -2.673689650697085e+00, -2.173086673284322e+00, -1.646192033039295e+00, -1.111179579412363e+00, -7.149807074170405e-01, -6.043867017834914e-01, -5.061998597397970e-01, -3.770949930189614e-01, -2.486486901595156e-01, -1.354284293122360e-01, -4.965734503945361e-02, -1.081341178891111e-02, -1.216204313328865e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


